bug_report:
[modules] ICE in check_return_expr from imported defaulted function
The following sample:

  // a.cpp
  module;
  struct exception_ptr {
    friend bool operator==(const exception_ptr&, const exception_ptr&) noexcept = default;
  };
  export module ThreadPool:Task;
  export template <typename = int> void enqueue() {
    exception_ptr e;
    e == e;
  }

  // b.cpp
  module;
  struct exception_ptr {
    friend bool operator==(const exception_ptr&, const exception_ptr&) noexcept = default;
  };
  export module ThreadPool;
  export import :Task;

  // c.cpp
  import ThreadPool;
  int main() { enqueue(); }

